from collections import deque

class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None
        self.nextRight = None

def connect(root):
    if not root:
        return

    queue = deque([root])

    while queue:
        level_size = len(queue)
        prev = None

        for _ in range(level_size):
            node = queue.popleft()

            if prev:
                prev.nextRight = node

            prev = node

            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)

        node.nextRight = None

def inorder(root):
    if not root:
        return
    inorder(root.left)
    print(root.data, end=' ')
    inorder(root.right)

def level_order(root):
    if not root:
        return

    current = root
    while current:
        temp = current
        while temp:
            print(temp.data, end=' ')
            temp = temp.nextRight
        print()
        current = current.left

